<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>DSWD Walk-in Kiosk</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link href="https://fonts.googleapis.com/icon?family=Material+Icons" rel="stylesheet">
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#eef2f7;color:#111827;min-height:100vh}.screen{min-height:100vh;display:none}.screen.active{display:flex}.start-screen{align-items:center;justify-content:center;padding:30px;background:linear-gradient(135deg,#0b2e83,#168fcb)}.start-card{width:820px;max-width:96%;background:#fff;border-radius:28px;padding:48px 38px;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,.28)}.logo-circle{width:116px;height:116px;border-radius:50%;margin:0 auto 20px;display:flex;align-items:center;justify-content:center;background:#eff6ff;color:#0b2e83}.logo-circle .material-icons{font-size:64px}.start-card h1{margin:0;font-size:42px;color:#00008b}.start-card p{margin:14px auto 22px;font-size:18px;color:#374151;line-height:1.5;max-width:650px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.step{background:#f8fafc;border:1px solid #e5e7eb;border-radius:14px;padding:14px}.step b{display:block;color:#0b2e83;margin-bottom:4px}.tap-btn{border:none;border-radius:999px;background:#0b2e83;color:#fff;font-size:24px;font-weight:900;padding:20px 48px;cursor:pointer;box-shadow:0 12px 26px rgba(11,46,131,.28)}.form-screen{align-items:stretch;justify-content:center;padding:24px}.kiosk-shell{width:1180px;max-width:100%;display:flex;flex-direction:column;min-height:calc(100vh - 48px)}.topbar{background:#0b2e83;color:white;padding:18px 22px;border-radius:18px 18px 0 0;display:flex;align-items:center;justify-content:space-between;gap:14px}.topbar h1{margin:0;font-size:26px}.topbar p{margin:4px 0 0;opacity:.9;font-size:14px}.home-btn{border:none;border-radius:10px;background:rgba(255,255,255,.16);color:white;padding:12px 16px;font-weight:900;cursor:pointer;display:inline-flex;align-items:center;gap:6px}.form-card{background:#fff;border:1px solid #d6dce8;border-top:0;border-radius:0 0 18px 18px;padding:22px;flex:1;overflow:auto}.helper-note{background:#eff6ff;border:1px solid #bfdbfe;color:#1e40af;padding:14px 16px;border-radius:12px;font-size:15px;font-weight:800;margin-bottom:18px}.prio-note{background:#fff7ed;border-color:#fed7aa;color:#9a3412}.address-note{background:#ecfeff;border-color:#a5f3fc;color:#155e75}.error-note{background:#fef2f2;border-color:#fecaca;color:#991b1b;display:none}.section-title{margin:20px 0 14px;color:#0f2f56;display:flex;align-items:center;gap:8px;font-size:19px}.section-title:first-of-type{margin-top:0}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.field-group{display:flex;flex-direction:column}.field-group label{font-size:14px;font-weight:900;color:#374151;margin-bottom:7px}.optional{font-size:12px;color:#64748b;font-weight:800}.field-group input,.field-group select{height:50px;padding:0 14px;border:1px solid #cbd5e1;border-radius:10px;font-size:16px;background:white;outline:none;width:100%}.field-group input:focus,.field-group select:focus{border-color:#168fcb;box-shadow:0 0 0 3px rgba(22,143,203,.12)}.field-group input.invalid,.field-group select.invalid{border-color:#ef4444;background:#fff7f7}.field-group select:disabled{background:#f1f5f9;color:#64748b}.two{grid-column:span 2}.full{grid-column:1/-1}.actions{display:flex;gap:12px;margin-top:24px;flex-wrap:wrap}.submit-btn,.clear-btn{min-height:54px;border:none;border-radius:12px;padding:0 24px;font-size:16px;font-weight:900;cursor:pointer;display:inline-flex;align-items:center;gap:8px}.submit-btn{background:#168fcb;color:white}.clear-btn{background:#e5e7eb;color:#111827}.success-screen{align-items:center;justify-content:center;padding:30px;background:#f3f6fb}.success-card{width:720px;max-width:96%;background:white;border-radius:24px;padding:44px 34px;text-align:center;border:1px solid #d6dce8;box-shadow:0 14px 35px rgba(15,23,42,.14)}.success-icon{width:105px;height:105px;border-radius:50%;background:#dcfce7;color:#166534;display:flex;align-items:center;justify-content:center;margin:0 auto 20px}.success-icon .material-icons{font-size:60px}.success-card h1{margin:0;color:#166534;font-size:34px}.success-card p{color:#374151;font-size:17px;line-height:1.5}.code-box,.queue-box{background:#eff6ff;color:#00008b;border:1px solid #bfdbfe;padding:14px 18px;border-radius:12px;font-size:24px;font-weight:900;margin:10px auto;display:inline-block}.queue-box.prio{background:#fff7ed;color:#c2410c;border-color:#fed7aa}.done-btn{border:none;border-radius:999px;background:#0b2e83;color:white;font-size:18px;font-weight:900;padding:16px 34px;cursor:pointer}.address-preview{min-height:50px;display:flex;align-items:center;padding:12px 14px;border:1px solid #bae6fd;background:#f0f9ff;border-radius:10px;font-size:15px;font-weight:800;color:#155e75}.loading-small{font-size:12px;color:#64748b;margin-top:5px;font-weight:800}.field-hint{font-size:12px;color:#64748b;margin-top:5px;font-weight:800}.field-error{font-size:12px;color:#dc2626;margin-top:5px;font-weight:900;display:none}@media(max-width:1000px){.form-grid,.steps{grid-template-columns:repeat(2,1fr)}.two{grid-column:span 1}.full{grid-column:1/-1}}@media(max-width:650px){.start-card h1{font-size:32px}.form-screen{padding:12px}.form-grid,.steps{grid-template-columns:1fr}.topbar{flex-direction:column;align-items:flex-start}}
</style>
</head>
<body>
<section id="startScreen" class="screen start-screen active"><div class="start-card"><div class="logo-circle"><span class="material-icons">how_to_reg</span></div><h1>DSWD Walk-in Registration</h1><p>Good day. Please register here first before proceeding inside. The guard/staff will use your record to verify your queue and direct you to assessment.</p><div class="steps"><div class="step"><b>1. Register</b>Enter your basic details.</div><div class="step"><b>2. Get Queue</b>PWD, pregnant, and seniors are priority.</div><div class="step"><b>3. Wait for Call</b>Proceed when your queue is called.</div></div><button class="tap-btn" onclick="showForm()">Tap to Register</button></div></section>
<section id="formScreen" class="screen form-screen"><div class="kiosk-shell"><div class="topbar"><div><h1>Guard Walk-in Registration</h1><p>Client-facing form for fast intake before verification.</p></div><button class="home-btn" type="button" onclick="goHome()"><span class="material-icons">home</span> Home</button></div>
<form id="kioskForm" action="../api/add_walkin.php" method="POST" class="form-card" onsubmit="return prepareAndValidateForm(event)"><input type="hidden" name="source" value="kiosk"><input type="hidden" name="birthday_month" id="birthdayMonth"><input type="hidden" name="birthday_day" id="birthdayDay"><input type="hidden" name="birthday_year" id="birthdayYear"><div class="helper-note">After submission, the system automatically creates your queue number. PWD, pregnant clients, and seniors are marked priority.</div><div class="helper-note prio-note" id="priorityPreview" style="display:none;">Priority queue preview: PRIO will be generated.</div><div class="helper-note error-note" id="formError"></div>
<h3 class="section-title"><span class="material-icons">person</span>Personal Information</h3><div class="form-grid">
<div class="field-group"><label>Last Name *</label><input type="text" name="last_name" required autocomplete="off" maxlength="80"></div><div class="field-group"><label>First Name *</label><input type="text" name="first_name" required autocomplete="off" maxlength="80"></div><div class="field-group"><label>Middle Name</label><input type="text" name="middle_name" autocomplete="off" maxlength="80"></div><div class="field-group"><label>Ext. Name <span class="optional">Optional</span></label><input type="text" name="ext_name" placeholder="Jr., Sr., III" autocomplete="off" maxlength="15"></div>
<div class="field-group"><label>Birthday *</label><input type="date" id="birthdayInput" required autocomplete="off"><div class="field-error" id="birthdayError">Please select a valid birthday.</div></div><div class="field-group"><label>Age *</label><input type="number" name="age" id="ageInput" min="0" max="130" required readonly></div><div class="field-group"><label>Sex *</label><select name="sex" id="sexSelect" required><option value="">Select</option><option value="Male">Male</option><option value="Female">Female</option></select></div><div class="field-group"><label>PWD? *</label><select name="sms_opt_in" id="pwdSelect" required><option value="0">No</option><option value="1">Yes - Priority</option></select></div>
<div class="field-group" id="pregnantGroup"><label>Pregnant? *</label><select name="is_pregnant" id="pregnantSelect" required><option value="0">No</option><option value="1">Yes - Priority</option></select></div><div class="field-group"><label>Contact Number</label><input type="tel" name="contact_number" id="contactInput" placeholder="09XXXXXXXXX or +639XXXXXXXXX" autocomplete="off" maxlength="13" inputmode="tel"><div class="field-hint">Allowed: 09XXXXXXXXX or +639XXXXXXXXX only.</div><div class="field-error" id="contactError">Use 11-digit 09XXXXXXXXX or +63 format.</div></div><div class="field-group"><label>ID Presented</label><select name="national_id"><option value="None">None</option><option value="PhilSys ID">PhilSys ID</option><option value="Senior Citizen ID">Senior Citizen ID</option><option value="PWD ID">PWD ID</option><option value="Barangay Certificate">Barangay Certificate</option><option value="Other ID">Other ID</option></select></div><div class="field-group"><label>Household ID</label><input type="text" name="household_id" id="householdInput" placeholder="HH-001 or numbers/letters" autocomplete="off" maxlength="30"><div class="field-hint">Letters, numbers, dash only. Max 30 characters.</div><div class="field-error" id="householdError">Household ID can only use letters, numbers, and dash.</div></div>
<div class="field-group"><label>Assistance Type *</label><select name="program_type" required><option value="AICS">AICS</option><option value="AKAP">AKAP</option><option value="Emergency Assistance">Emergency Assistance</option><option value="Medical Assistance">Medical Assistance</option><option value="Educational Assistance">Educational Assistance</option><option value="Other">Other</option></select></div>
</div>
<h3 class="section-title"><span class="material-icons">location_on</span>Address</h3><div class="helper-note address-note" id="addressStatus">Loading complete Philippine address list...</div><div class="form-grid">
<div class="field-group"><label>Region *</label><select name="region" id="regionSelect" required disabled><option value="">Loading regions...</option></select><div class="loading-small" id="regionHint"></div></div>
<div class="field-group"><label>Province *</label><select name="province" id="provinceSelect" required disabled><option value="">Select region first</option></select><div class="loading-small" id="provinceHint"></div></div>
<div class="field-group"><label>City / Municipality *</label><select name="city_municipality" id="citySelect" required disabled><option value="">Select province first</option></select><div class="loading-small" id="cityHint"></div></div>
<div class="field-group"><label>Barangay *</label><select name="barangay" id="barangaySelect" required disabled><option value="">Select city first</option></select><div class="loading-small" id="barangayHint"></div></div>
<div class="field-group two"><label>LGU *</label><input type="text" name="lgu" id="lguInput" readonly required></div><div class="field-group two"><label>Complete Address Preview</label><div class="address-preview" id="addressPreview">Select your address.</div></div>
</div><div class="actions"><button type="submit" class="submit-btn"><span class="material-icons">confirmation_number</span> Submit and Get Queue</button><button type="reset" class="clear-btn"><span class="material-icons">backspace</span> Clear Form</button></div></form></div></section>
<section id="successScreen" class="screen success-screen"><div class="success-card"><div class="success-icon"><span class="material-icons">check_circle</span></div><h1>Registration Complete</h1><p>Your record and queue number are now saved. Please show this screen to the guard or wait for your queue to be called.</p><div>Beneficiary Code</div><div class="code-box" id="codeBox">Saved</div><br><div>Queue Number</div><div class="queue-box" id="queueBox">Pending</div><br><button class="done-btn" onclick="goHome()">Done</button></div></section>
<script>
const API_PSGC='../api/psgc.php';
const regionSelect=document.getElementById('regionSelect'),provinceSelect=document.getElementById('provinceSelect'),citySelect=document.getElementById('citySelect'),barangaySelect=document.getElementById('barangaySelect'),lguInput=document.getElementById('lguInput'),birthdayInput=document.getElementById('birthdayInput'),ageInput=document.getElementById('ageInput'),pwdSelect=document.getElementById('pwdSelect'),pregnantSelect=document.getElementById('pregnantSelect'),sexSelect=document.getElementById('sexSelect'),priorityPreview=document.getElementById('priorityPreview'),addressStatus=document.getElementById('addressStatus'),addressPreview=document.getElementById('addressPreview'),contactInput=document.getElementById('contactInput'),householdInput=document.getElementById('householdInput'),formError=document.getElementById('formError');
const regionHint=document.getElementById('regionHint'),provinceHint=document.getElementById('provinceHint'),cityHint=document.getElementById('cityHint'),barangayHint=document.getElementById('barangayHint');
let selectedRegionCode='',selectedProvinceCode='',selectedCityCode='',independentRegionMode=false;
const today=new Date();const maxDate=today.toISOString().split('T')[0];const minDate=new Date(today.getFullYear()-130,today.getMonth(),today.getDate()).toISOString().split('T')[0];birthdayInput.max=maxDate;birthdayInput.min=minDate;
function setStatus(text,bad=false){try{addressStatus.textContent=text;addressStatus.style.background=bad?'#fef2f2':'#ecfeff';addressStatus.style.borderColor=bad?'#fecaca':'#a5f3fc';addressStatus.style.color=bad?'#991b1b':'#155e75'}catch(e){console.error(e)}}
function setFormError(msg){formError.textContent=msg||'';formError.style.display=msg?'block':'none';if(msg)formError.scrollIntoView({behavior:'smooth',block:'center'})}
function setInvalid(el,id,msg){try{if(el)el.classList.add('invalid');const er=document.getElementById(id);if(er){er.textContent=msg;er.style.display='block'}}catch(e){console.error(e)}}
function clearInvalid(el,id){try{if(el)el.classList.remove('invalid');const er=document.getElementById(id);if(er)er.style.display='none'}catch(e){console.error(e)}}
function sortByName(a,b){return String(a.name||'').localeCompare(String(b.name||''))}
function fillSelect(select,items,placeholder){try{select.innerHTML='<option value="">'+placeholder+'</option>';(items||[]).sort(sortByName).forEach(item=>{const opt=document.createElement('option');opt.value=item.name||'';opt.textContent=item.name||'';opt.dataset.code=item.code||'';select.appendChild(opt)});select.disabled=false}catch(e){console.error(e);select.disabled=true}}
function resetSelect(select,placeholder){try{select.innerHTML='<option value="">'+placeholder+'</option>';select.disabled=true}catch(e){console.error(e)}}
async function getLocalPSGC(params){try{const url=API_PSGC+'?'+new URLSearchParams(params).toString();const res=await fetch(url,{cache:'no-store'});if(!res.ok)throw new Error('PSGC API request failed');const data=await res.json();if(!data.success)throw new Error(data.message||'PSGC data unavailable');return data.items||[]}catch(e){console.error(e);throw e}}
async function initPlaces(){try{setStatus('Loading all Philippine regions from local PSGC cache...');resetSelect(provinceSelect,'Select region first');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');const regions=await getLocalPSGC({type:'regions'});fillSelect(regionSelect,regions,'Select Region');regionHint.textContent=regions.length+' regions loaded';setStatus('Address dropdown ready. Select Region → Province → City/Municipality → Barangay.')}catch(e){setStatus('Unable to load address list. For offline mode, run api/seed_psgc_all.php first.',true)}}
async function updateProvinces(){try{selectedRegionCode=regionSelect.selectedOptions[0]?.dataset.code||'';selectedProvinceCode='';selectedCityCode='';independentRegionMode=false;lguInput.value='';updateAddressPreview();resetSelect(provinceSelect,'Loading provinces...');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');provinceHint.textContent='';cityHint.textContent='';barangayHint.textContent='';if(!selectedRegionCode){resetSelect(provinceSelect,'Select region first');return}const provinces=await getLocalPSGC({type:'provinces',region_code:selectedRegionCode});const items=provinces.map(p=>({name:p.name,code:p.code}));items.push({name:'Independent City / No Province',code:'REGION_CITIES'});fillSelect(provinceSelect,items,'Select Province');provinceHint.textContent=provinces.length+' provinces + independent city option'}catch(e){setStatus('Failed to load provinces. Please refresh or seed PSGC data.',true)}}
async function updateCities(){try{selectedProvinceCode=provinceSelect.selectedOptions[0]?.dataset.code||'';selectedCityCode='';independentRegionMode=selectedProvinceCode==='REGION_CITIES';lguInput.value='';updateAddressPreview();resetSelect(citySelect,'Loading cities/municipalities...');resetSelect(barangaySelect,'Select city first');cityHint.textContent='';barangayHint.textContent='';if(!selectedProvinceCode){resetSelect(citySelect,'Select province first');return}const params=independentRegionMode?{type:'cities',region_code:selectedRegionCode}:{type:'cities',region_code:selectedRegionCode,province_code:selectedProvinceCode};const cities=await getLocalPSGC(params);fillSelect(citySelect,cities,'Select City / Municipality');cityHint.textContent=cities.length+' cities/municipalities loaded'}catch(e){setStatus('Failed to load cities/municipalities. Please refresh or seed PSGC data.',true)}}
async function updateBarangays(){try{selectedCityCode=citySelect.selectedOptions[0]?.dataset.code||'';lguInput.value=citySelect.value||'';updateAddressPreview();resetSelect(barangaySelect,'Loading barangays...');barangayHint.textContent='';if(!selectedCityCode){resetSelect(barangaySelect,'Select city first');return}const barangays=await getLocalPSGC({type:'barangays',region_code:selectedRegionCode,province_code:independentRegionMode?'':selectedProvinceCode,city_code:selectedCityCode});fillSelect(barangaySelect,barangays,'Select Barangay');barangayHint.textContent=barangays.length+' barangays loaded'}catch(e){setStatus('Failed to load barangays. Please refresh or seed PSGC data.',true)}}
function updateAddressPreview(){try{const brgy=barangaySelect.value,city=citySelect.value,province=provinceSelect.value==='Independent City / No Province'?'':provinceSelect.value,region=regionSelect.value;const parts=[brgy,city,province,region].filter(Boolean);addressPreview.textContent=parts.length?parts.join(', '):'Select your address.';lguInput.value=city||''}catch(e){console.error(e)}}
regionSelect.addEventListener('change',()=>{updateProvinces().catch(console.error)});provinceSelect.addEventListener('change',()=>{updateCities().catch(console.error)});citySelect.addEventListener('change',()=>{updateBarangays().catch(console.error)});barangaySelect.addEventListener('change',updateAddressPreview);initPlaces().catch(console.error);
function updatePriority(){try{const age=parseInt(ageInput.value||'0',10);if(sexSelect.value!=='Female')pregnantSelect.value='0';pregnantSelect.disabled=sexSelect.value!=='Female';priorityPreview.style.display=(pwdSelect.value==='1'||pregnantSelect.value==='1'||age>=60)?'block':'none'}catch(e){console.error(e)}}pwdSelect.addEventListener('change',updatePriority);pregnantSelect.addEventListener('change',updatePriority);sexSelect.addEventListener('change',updatePriority);
function autoAge(){try{if(!birthdayInput.value)return;const b=new Date(birthdayInput.value+'T00:00:00');if(isNaN(b.getTime()))return;const t=new Date();let age=t.getFullYear()-b.getFullYear();const mo=t.getMonth()-b.getMonth();if(mo<0||(mo===0&&t.getDate()<b.getDate()))age--;ageInput.value=(age>=0&&age<=130)?age:'';updatePriority()}catch(e){console.error(e)}}birthdayInput.addEventListener('change',autoAge);birthdayInput.addEventListener('input',autoAge);
function normalizeContact(){try{let v=contactInput.value.trim().replace(/[^0-9+]/g,'');if(v.startsWith('+'))v='+'+v.replace(/\+/g,'');else v=v.replace(/\+/g,'');if(v.startsWith('63')&&v.length===12)v='+'+v;if(v.length>13)v=v.slice(0,13);contactInput.value=v}catch(e){console.error(e)}}
function isValidContact(){try{const v=contactInput.value.trim();if(v==='')return true;return /^09\d{9}$/.test(v)||/^\+639\d{9}$/.test(v)}catch(e){console.error(e);return false}}
function validateContact(){normalizeContact();const ok=isValidContact();if(ok)clearInvalid(contactInput,'contactError');else setInvalid(contactInput,'contactError','Use 11-digit 09XXXXXXXXX or +639XXXXXXXXX format.');return ok}
function validateHousehold(){try{let v=householdInput.value.trim().toUpperCase().replace(/[^A-Z0-9-]/g,'');if(v.length>30)v=v.slice(0,30);householdInput.value=v;const ok=v===''||/^[A-Z0-9-]{1,30}$/.test(v);if(ok)clearInvalid(householdInput,'householdError');else setInvalid(householdInput,'householdError','Household ID can only use letters, numbers, and dash.');return ok}catch(e){console.error(e);return false}}
contactInput.addEventListener('input',validateContact);contactInput.addEventListener('blur',validateContact);householdInput.addEventListener('input',validateHousehold);householdInput.addEventListener('blur',validateHousehold);
function prepareBirthday(){try{clearInvalid(birthdayInput,'birthdayError');if(!birthdayInput.value){setInvalid(birthdayInput,'birthdayError','Please select a valid birthday.');return false}const d=new Date(birthdayInput.value+'T00:00:00');if(isNaN(d.getTime())||d>today||d<new Date(minDate+'T00:00:00')){setInvalid(birthdayInput,'birthdayError','Birthday must be valid and not future date.');return false}document.getElementById('birthdayMonth').value=d.getMonth()+1;document.getElementById('birthdayDay').value=d.getDate();document.getElementById('birthdayYear').value=d.getFullYear();autoAge();return ageInput.value!==''}catch(e){console.error(e);setInvalid(birthdayInput,'birthdayError','Birthday validation failed.');return false}}
function validateAddress(){try{let ok=true;[regionSelect,provinceSelect,citySelect,barangaySelect].forEach(el=>{if(!el.value){el.classList.add('invalid');ok=false}else el.classList.remove('invalid')});if(!ok)setFormError('Please complete the address dropdowns.');return ok}catch(e){console.error(e);return false}}
function prepareAndValidateForm(event){try{setFormError('');const b=prepareBirthday(),c=validateContact(),h=validateHousehold(),a=validateAddress();if(!b||!c||!h||!a){if(event)event.preventDefault();setFormError('Please fix the highlighted fields before submitting.');return false}return true}catch(e){console.error(e);if(event)event.preventDefault();setFormError('Something went wrong while validating the form. Please refresh and try again.');return false}}
function showOnly(id){try{document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active')}catch(e){console.error(e)}}function showForm(){showOnly('formScreen');updatePriority()}function goHome(){try{document.getElementById('kioskForm').reset();setFormError('');document.querySelectorAll('.invalid').forEach(el=>el.classList.remove('invalid'));document.querySelectorAll('.field-error').forEach(el=>el.style.display='none');priorityPreview.style.display='none';updatePriority();resetSelect(provinceSelect,'Select region first');resetSelect(citySelect,'Select province first');resetSelect(barangaySelect,'Select city first');lguInput.value='';addressPreview.textContent='Select your address.';showOnly('startScreen')}catch(e){console.error(e)}}
try{const params=new URLSearchParams(window.location.search);if(params.get('success')==='1'){const code=params.get('code')||'Saved',queue=params.get('queue')||'Pending',type=params.get('type')||'';document.getElementById('codeBox').innerText=code;const qb=document.getElementById('queueBox');qb.innerText=queue;if(type==='priority')qb.classList.add('prio');showOnly('successScreen');window.history.replaceState({},document.title,'index.php')}}catch(e){console.error(e)}updatePriority();
</script>
</body>
</html>